===================================================================
--- index.html
+++ index.html
@@ -11,4 +11,19 @@
 <div class="map-wrap"><div class="map-title">DISTRICT MAP</div><canvas id="minimap" width="162" height="162"></canvas></div><div id="toast" class="toast">PACKAGE SECURED</div><div id="vehicle-tag" class="vehicle-tag">◈ NIGHTRUNNER · TURBO READY</div><div id="prompt" class="center-prompt"></div><div id="flash" class="damage-flash"></div><div class="bottom"><div class="controls"><div class="hint"><span class="key">WASD</span> MOVE</div><div class="hint"><span class="key">MOUSE</span> AIM</div><div class="hint"><span class="key">CLICK</span> FIRE</div><div class="hint"><span class="key">E</span> CAR / USE</div><div class="hint"><span class="key">SHIFT</span> SPRINT</div></div><div class="bottom-right">A CITY THAT NEVER<br>STOPS MOVING</div></div>
 <div class="mobile-controls"><div id="joy" class="joy"><div id="joy-knob" class="joy-knob"></div></div><div class="touch-actions"><button id="touch-boost" class="touch-btn boost">DASH</button><button id="touch-interact" class="touch-btn interact">ENTER</button><button id="touch-hit" class="touch-btn fire">FIRE</button><button id="touch-melee" class="touch-btn">MELEE</button></div></div></div>
 <div id="start-screen"><div class="intro"><div class="intro-overline">PACIFIC CITY — AFTER HOURS</div><h1>THE<br><span>NIGHT</span><br>SHIFT</h1><p>One last run. Three ghost packages scattered across the district. Pick your route, keep your head down, and make the extraction before sunrise.</p><div class="start-row"><button id="play" class="play-btn">ENTER THE DISTRICT&nbsp; ↗</button><div class="start-hint">WASD to move · mouse to aim<br>click to fire · E to interact</div></div></div><div class="intro-footer">AN OPEN-CITY ACTION RPG · BUILT FOR THE AFTER HOURS</div></div>
 <script>
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mini=document.querySelector('#minimap'),mctx=mini.getContext('2d');
+let W=innerWidth,H=innerHeight,DPR=1,now=0,last=0,toastTimer=0,shake=0;
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
+const world={w:2400,h:1980,step:420,road:112},camera={x:0,y:0};const keys={},mouse={x:W/2,y:H/2,down:false};let playing=false,gameOver=false,missionDone=false;
+const player={x:175,y:120,angle:0,hp:100,maxHp:100,speed:0,cash:0,xp:0,level:1,fire:0,melee:0,dash:0,invuln:0,vehicle:null,kills:0};const blocks=[],trees=[],cars=[],enemies=[],bullets=[],drops=[],particles=[];
+const packages=[{x:540,y:335,got:false},{x:1380,y:755,got:false},{x:960,y:1595,got:false}],extract={x:2220,y:1800};
+function randSeed(seed){let n=seed;return()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296}}
+function makeCity(){const rnd=randSeed(78231);for(let ix=0;ix<5;ix++)for(let iy=0;iy<4;iy++){let x=176+ix*420,y=176+iy*420;if(x>world.w-100||y>world.h-100)continue;let bw=300+(rnd()-.5)*18,bh=300+(rnd()-.5)*18,bx=x+(rnd()-.5)*12,by=y+(rnd()-.5)*12;let palette=['#3c4b48','#414b4a','#4a514c','#434a53','#4e514a','#394948'];blocks.push({x:bx,y:by,w:bw,h:bh,c:palette[Math.floor(rnd()*palette.length)],kind:Math.floor(rnd()*4),seed:rnd()});if(rnd()>.25){trees.push({x:bx-13-rnd()*10,y:by+40+rnd()*(bh-70),r:8+rnd()*3});trees.push({x:bx+bw+12+rnd()*8,y:by+60+rnd()*(bh-90),r:8+rnd()*3})}if(rnd()>.48)trees.push({x:bx+bw*.52,y:by+bh+13,r:7})}}
+for(let i=0;i<8;i++){let horizontal=i<4,cx=horizontal?350+i*420:120+Math.floor((i-4)/2)*840,cy=horizontal?120+Math.floor(i/2)*840:400+(i-4)*420;cars.push({x:cx,y:cy,angle:horizontal?0:Math.PI/2,color:['#eab16e','#83a9a0','#d96e5e','#8798b8','#d1d1b3'][i%5],speed:0,parked:true})}makeCity();
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function circleRect(cx,cy,r,b){let px=clamp(cx,b.x,b.x+b.w),py=clamp(cy,b.y,b.y+b.h);return (cx-px)**2+(cy-py)**2<r*r}function blocked(x,y,r){return blocks.some(b=>circleRect(x,y,r,b))}
+function showToast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.2}function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=20+Math.random()*100;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+Math.random()*.45,color,r:1+Math.random()*2})}}
+function spawnEnemies(){[[800,120],[1800,540],[120,1200],[1800,1380],[960,1800],[540,960]].forEach((p,i)=>enemies.push({x:p[0],y:p[1],angle:Math.random()*6.28,hp:3,maxHp:3,speed:43+Math.random()*12,fire:1+Math.random()*2,alert:0,dead:false,id:i}))}spawnEnemies();
+function updateUI(){let hpPct=player.hp/player.maxHp*100;document.querySelector('#health-bar').style.width=hpPct+'%';document.querySelector('#health-text').textContent=Math.ceil(player.hp)+' / '+player.maxHp;document.querySelector('#xp-bar').style.width=(player.xp%100)+'%';document.querySelector('#xp-text').textContent=(player.xp%100)+' / 100 XP';document.querySelector('#cash').textContent='$ '+player.cash.toLocaleString();document.querySelector('#rank').textContent=String(player.level).padStart(2,'0');let stars=Math.min(5,Math.ceil(player.kills/2));document.querySelector('#wanted').textContent='★'.repeat(stars)+'☆'.repeat(5-stars);let count=packages.filter(p=>p.got).length;document.querySelector('#objective-count').textContent=count+' / 3';document.querySelector('#mission-progress').style.width=(count/3*100)+'%';document.querySelector('#objective').innerHTML=missionDone?'▸ <b>Job complete</b> — free roam':count<3?'▸ Recover the remaining <b>ghost packages</b>':'▸ Reach the <b>extraction point</b>';document.querySelector('#vehicle-tag').classList.toggle('on',!!player.vehicle)}updateUI();
+function drawRoads(){ctx.fillStyle='#192522';ctx.fillRect(0,0,world.w,world.h);for(let i=0;i<850;i++){let x=(i*173)%world.w,y=(i*313)%world.h;ctx.fillStyle=i%2?'#ffffff05':'#050b0910';ctx.fillRect(x,y,2,2)}for(let x=120;x<world.w+200;x+=world.step){ctx.fillStyle='#59615a';ctx.fillRect(x-world.road/2-9,0,world.road+18,world.h);ctx.fillStyle='#252e2d';ctx.fillRect(x-world.road/2,0,world.road,world.h);ctx.fillStyle='#d5bc7950';ctx.fillRect(x-1,0,2,world.h);ctx.fillStyle='#ffffff12';for(let y=20;y<world.h;y+=46)ctx.fillRect(x-34,y,2,22);for(let y=60;y<world.h;y+=46)ctx.fillRect(x+32,y,2,22)}for(let y=120;y<world.h+200;y+=world.step){ctx.fillStyle='#59615a';ctx.fillRect(0,y-world.road/2-9,world.w,world.road+18);ctx.fillStyle='#252e2d';ctx.fillRect(0,y-world.road/2,world.w,world.road);ctx.fillStyle='#d5bc7950';ctx.fillRect(0,y-1,world.w,2);ctx.fillStyle='#ffffff12';for(let x=20;x<world.w;x+=46)ctx.fillRect(x,y-34,22,2);for(let x=60;x<world.w;x+=46)ctx.fillRect(x,y+32,22,2)}for(let x=120;x<world.w;x+=world.step)for(let y=120;y<world.h;y+=world.step){ctx.fillStyle='#d9dfd01a';for(let j=-4;j<=4;j++){ctx.fillRect(x+j*8-2,y-64,4,13);ctx.fillRect(x+j*8-2,y+51,4,13);ctx.fillRect(x-64,y+j*8-2,13,4);ctx.fillRect(x+51,y+j*8-2,13,4)}}}
+function drawBuilding(b){ctx.save();ctx.translate(b.x,b.y);ctx.fillStyle='#0008';ctx.fillRect(8,10,b.w,b.h);ctx.fillStyle='#77776c';ctx.fillRect(-8,-8,b.w+16,b.h+16);ctx.fillStyle=b.c;ctx.fillRect(0,0,b.w,b.h);ctx.fillStyle='#ffffff0b';ctx.fillRect(7,7,b.w-14,4);ctx.fillStyle='#111b1c';ctx.fillRect(12,12,b.w-24,b.h-24);let q=22;ctx.fillStyle=b.c;ctx.fillRect(q,q,b.w-2*q,b.h-2*q);ctx.strokeStyle='#e7e2ca22';ctx.lineWidth=2;ctx.strokeRect(q,q,b.w-2*q,b.h-2*q);if(b.kind===0){ctx.fillStyle='#65706a';ctx.fillRect(45,40,100,75);ctx.fillRect(165,145,82,82);ctx.fillStyle='#202b29';ctx.fillRect(52,47,85,61);ctx.fillRect(172,152,68,67);ctx.fillStyle='#d1b56c';ctx.fillRect(57,52,16,6);ctx.fillRect(177,157,24,5)}else if(b.kind===1){ctx.fillStyle='#5e6860';ctx.fillRect(42,38,b.w-84,45);ctx.fillStyle='#37413e';for(let i=0;i<5;i++)ctx.fillRect(53+i*44,46,22,28);ctx.fillStyle='#4b5550';ctx.fillRect(42,120,72,100);ctx.fillStyle='#e5c777';ctx.beginPath();ctx.arc(190,178,28,0,6.3);ctx.fill();ctx.fillStyle='#171f1e';ctx.beginPath();ctx.arc(190,178,22,0,6.3);ctx.fill()}else if(b.kind===2){ctx.fillStyle='#59635d';ctx.fillRect(48,42,90,90);ctx.fillRect(155,42,90,50);ctx.fillStyle='#313c39';ctx.fillRect(56,50,74,74);ctx.fillRect(163,50,74,34);ctx.fillStyle='#a18e62';for(let i=0;i<3;i++){ctx.fillRect(54+i*27,155,15,65);ctx.fillStyle='#38433f';ctx.fillRect(57+i*27,160,9,55);ctx.fillStyle='#a18e62'}}else{ctx.fillStyle='#53605a';ctx.fillRect(42,42,215,185);ctx.fillStyle='#303c38';ctx.fillRect(51,51,196,167);ctx.strokeStyle='#a18e5c';ctx.lineWidth=5;ctx.beginPath();ctx.arc(149,134,55,0,6.3);ctx.stroke();ctx.fillStyle='#dfb972';ctx.fillRect(136,70,26,6)}ctx.fillStyle='#27332f';for(let i=0;i<5;i++){let vx=35+((i*57+b.seed*99)%225),vy=35+((i*91+b.seed*123)%225);ctx.fillRect(vx,vy,14,10);ctx.fillStyle='#84918a';ctx.fillRect(vx+2,vy+2,10,2);ctx.fillStyle='#27332f'}ctx.fillStyle='#e6b365';for(let i=0;i<4;i++)ctx.fillRect(26+i*72,b.h-5,24,3);ctx.restore()}

