function drawTree(t){let p={x:t.x,y:t.y};ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(4,8,t.r*1.2,t.r*.7,0,0,7);ctx.fill();ctx.fillStyle='#263a33';ctx.beginPath();ctx.arc(0,0,t.r,0,7);ctx.fill();ctx.fillStyle='#355447';ctx.beginPath();ctx.arc(-2,-3,t.r*.72,0,7);ctx.fill();ctx.fillStyle='#54735d';ctx.beginPath();ctx.arc(-4,-5,t.r*.35,0,7);ctx.fill();ctx.restore()}
function drawCar(c){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);ctx.fillStyle='#0009';ctx.beginPath();ctx.roundRect(-23,-13,49,31,7);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.roundRect(-25,-15,50,30,6);ctx.fill();ctx.fillStyle='#192725';ctx.beginPath();ctx.roundRect(-11,-11,22,22,5);ctx.fill();ctx.fillStyle='#b9d1c6';ctx.fillRect(-8,-10,14,4);ctx.fillStyle='#6eb3aa';ctx.fillRect(-8,6,14,4);ctx.fillStyle='#f7d796';ctx.fillRect(20,-10,4,6);ctx.fillRect(20,5,4,6);ctx.fillStyle='#fa7561';ctx.fillRect(-24,-10,3,5);ctx.fillRect(-24,5,3,5);ctx.fillStyle='#111';ctx.fillRect(-16,-16,10,3);ctx.fillRect(8,-16,10,3);ctx.fillRect(-16,13,10,3);ctx.fillRect(8,13,10,3);ctx.restore()}
function drawActor(x,y,angle,color,playerActor=false){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(1,5,10,7,0,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,1,7,10,0,0,7);ctx.fill();ctx.fillStyle=playerActor?'#dce5d8':'#e5b29b';ctx.beginPath();ctx.arc(0,-7,5,0,7);ctx.fill();ctx.fillStyle=playerActor?'#6af0c1':'#ffb085';ctx.fillRect(4,-2,8,3);ctx.fillStyle='#172321';ctx.fillRect(-4,7,3,4);ctx.fillRect(2,7,3,4);ctx.restore()}
function drawMarker(x,y,color,label){let pulse=.65+.35*Math.sin(now*3.4+y);ctx.save();ctx.globalAlpha=.3*pulse;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,24+Math.sin(now*3+y)*3,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,12,0,7);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,3,0,7);ctx.fill();ctx.font='9px DM Mono,monospace';ctx.textAlign='center';ctx.fillText(label,x,y-20);ctx.restore()}
function aimPoint(){let wpos={x:mouse.x+camera.x,y:mouse.y+camera.y};if('ontouchstart'in window){let target=enemies.filter(e=>!e.dead).sort((a,b)=>dist(player,a)-dist(player,b))[0];if(target)wpos=target}return wpos}
function movePlayer(dt){let axisX=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),axisY=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);if(touchMove.active){axisX=touchMove.x;axisY=touchMove.y}let mag=Math.hypot(axisX,axisY);if(mag>1){axisX/=mag;axisY/=mag}if(player.vehicle){let c=player.vehicle;let accel=axisY<0?1:axisY>0?-.75:0;c.speed+=accel*250*dt;c.speed*=Math.pow(.985,dt*60);if(keys.ShiftLeft||touchBoost)c.speed*=Math.pow(.993,dt*60);c.speed=clamp(c.speed,-130,330);if(Math.abs(c.speed)>4)c.angle+=axisX*dt*(c.speed/100);let nx=c.x+Math.cos(c.angle)*c.speed*dt,ny=c.y+Math.sin(c.angle)*c.speed*dt;if(!blocked(nx,ny,20)){c.x=clamp(nx,20,world.w-20);c.y=clamp(ny,20,world.h-20)}else{c.speed*=-.25;burst(c.x,c.y,'#ffb568',3)}player.x=c.x;player.y=c.y;player.angle=c.angle}else{let speed=(keys.ShiftLeft||keys.ShiftRight||touchBoost?205:145);if(player.dash>0)speed=360;let nx=player.x+axisX*speed*dt,ny=player.y+axisY*speed*dt;if(!blocked(nx,player.y,9))player.x=clamp(nx,10,world.w-10);if(!blocked(player.x,ny,9))player.y=clamp(ny,10,world.h-10);let aim=aimPoint();player.angle=Math.atan2(aim.y-player.y,aim.x-player.x)}camera.x=clamp(player.x-W/2,0,world.w-W);camera.y=clamp(player.y-H/2,0,world.h-H)}
function tryInteract(){if(player.vehicle){let c=player.vehicle;player.vehicle=null;c.speed=0;let sx=-Math.sin(c.angle)*35,sy=Math.cos(c.angle)*35;player.x=clamp(c.x+sx,10,world.w-10);player.y=clamp(c.y+sy,10,world.h-10);showToast('ON FOOT · STAY SHARP');return}let nearest=cars.filter(c=>dist(c,player)<54).sort((a,b)=>dist(a,player)-dist(b,player))[0];if(nearest){player.vehicle=nearest;player.x=nearest.x;player.y=nearest.y;player.angle=nearest.angle;showToast('NIGHTRUNNER ACQUIRED · W TO DRIVE');return}let count=packages.filter(p=>p.got).length;if(count===3&&!missionDone&&dist(player,extract)<80){missionDone=true;player.cash+=1200;player.xp+=100;showToast('JOB COMPLETE · +$1,200 · +100 XP');updateUI()}}
function shoot(){if(player.fire>0||player.vehicle)return;player.fire=.18;let a=player.angle;bullets.push({x:player.x+Math.cos(a)*13,y:player.y+Math.sin(a)*13,vx:Math.cos(a)*590,vy:Math.sin(a)*590,life:.85,owner:'player'});burst(player.x+Math.cos(a)*13,player.y+Math.sin(a)*13,'#ffcc7c',2)}
function melee(){if(player.melee>0||player.vehicle)return;player.melee=.55;let hit=false;for(let e of enemies){if(e.dead)continue;let d=dist(e,player),a=Math.atan2(e.y-player.y,e.x-player.x),dif=Math.atan2(Math.sin(a-player.angle),Math.cos(a-player.angle));if(d<43&&Math.abs(dif)<1.15){e.hp-=2;e.alert=4;hit=true;burst(e.x,e.y,'#ff9b74',7);if(e.hp<=0)killEnemy(e)}}if(hit)showToast('CLEAN HIT')}
function killEnemy(e){e.dead=true;player.kills++;player.cash+=85;player.xp+=32;drops.push({x:e.x,y:e.y,type:'cash',life:18});burst(e.x,e.y,'#ff765f',14);if(player.xp>=100){player.xp-=100;player.level++;player.maxHp+=10;player.hp=Math.min(player.maxHp,player.hp+30);showToast('RANK UP · VITALS RESTORED')}updateUI()}
function updateEnemies(dt){for(let e of enemies){if(e.dead)continue;let d=dist(e,player);if(d<340||e.alert>0)e.alert=3;else e.alert=Math.max(0,e.alert-dt);if(e.alert>0){let a=Math.atan2(player.y-e.y,player.x-e.x);e.angle=a;if(d>116){let nx=e.x+Math.cos(a)*e.speed*dt,ny=e.y+Math.sin(a)*e.speed*dt;if(!blocked(nx,ny,9)){e.x=nx;e.y=ny}}e.fire-=dt;if(e.fire<=0&&d<300&&!player.vehicle){e.fire=1.5+Math.random()*1.1;bullets.push({x:e.x+Math.cos(a)*9,y:e.y+Math.sin(a)*9,vx:Math.cos(a)*300,vy:Math.sin(a)*300,life:1.2,owner:'enemy'})}}else{e.angle+=Math.sin(now+e.id)*dt*.25}}
}

