const touchMove={x:0,y:0,active:false};let touchBoost=false,touchFire=false;
function movePlayer(dt){let axisX=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),axisY=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);if(touchMove.active){axisX=touchMove.x;axisY=touchMove.y}let mag=Math.hypot(axisX,axisY);if(mag>1){axisX/=mag;axisY/=mag}if(player.vehicle){let c=player.vehicle,accel=axisY<0?1:axisY>0?-.75:0;c.speed+=accel*250*dt;c.speed*=Math.pow(.985,dt*60);c.speed=clamp(c.speed,-130,330);if(Math.abs(c.speed)>4)c.angle+=axisX*dt*(c.speed/100);let nx=c.x+Math.cos(c.angle)*c.speed*dt,ny=c.y+Math.sin(c.angle)*c.speed*dt;if(!blocked(nx,ny,20)){c.x=clamp(nx,20,world.w-20);c.y=clamp(ny,20,world.h-20)}else{c.speed*=-.25;burst(c.x,c.y,'#ffb568',3)}player.x=c.x;player.y=c.y;player.angle=c.angle}else{let speed=(keys.ShiftLeft||keys.ShiftRight||touchBoost?205:145);if(player.dash>0)speed=360;let nx=player.x+axisX*speed*dt,ny=player.y+axisY*speed*dt;if(!blocked(nx,player.y,9))player.x=clamp(nx,10,world.w-10);if(!blocked(player.x,ny,9))player.y=clamp(ny,10,world.h-10);let aim=aimPoint();player.angle=Math.atan2(aim.y-player.y,aim.x-player.x)}camera.x=clamp(player.x-W/2,0,world.w-W);camera.y=clamp(player.y-H/2,0,world.h-H)}
function tryInteract(){if(player.vehicle){let c=player.vehicle;player.vehicle=null;c.speed=0;let sx=-Math.sin(c.angle)*35,sy=Math.cos(c.angle)*35;player.x=clamp(c.x+sx,10,world.w-10);player.y=clamp(c.y+sy,10,world.h-10);showToast('ON FOOT · STAY SHARP');return}let nearest=cars.filter(c=>dist(c,player)<54).sort((a,b)=>dist(a,player)-dist(b,player))[0];if(nearest){player.vehicle=nearest;player.x=nearest.x;player.y=nearest.y;player.angle=nearest.angle;showToast('NIGHTRUNNER ACQUIRED · W TO DRIVE');return}let count=packages.filter(p=>p.got).length;if(count===3&&!missionDone&&dist(player,extract)<80){missionDone=true;player.cash+=1200;player.xp+=100;showToast('JOB COMPLETE · +$1,200 · +100 XP');updateUI()}}
function shoot(){if(player.fire>0||player.vehicle)return;player.fire=.18;let a=player.angle;bullets.push({x:player.x+Math.cos(a)*13,y:player.y+Math.sin(a)*13,vx:Math.cos(a)*590,vy:Math.sin(a)*590,life:.85,owner:'player'});burst(player.x+Math.cos(a)*13,player.y+Math.sin(a)*13,'#ffcc7c',2)}
