function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;now=t/1000;if(playing&&!gameOver)updateWorld(dt);drawWorld();requestAnimationFrame(frame)}requestAnimationFrame(frame);

const startScreen=document.querySelector('#start-screen');
document.querySelector('#play').addEventListener('click',()=>{
 playing=true;startScreen.style.opacity='0';startScreen.style.pointerEvents='none';
 setTimeout(()=>startScreen.style.visibility='hidden',500);canvas.focus();
});
function setKey(code,down){keys[code]=down}
addEventListener('keydown',e=>{
 if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();
 if(e.repeat)return;setKey(e.code,true);
 if(!playing)return;
 if(e.code==='KeyE')tryInteract();
 if(e.code==='KeyF')melee();
 if(e.code==='Space')player.dash=.22;
});
addEventListener('keyup',e=>setKey(e.code,false));
addEventListener('blur',()=>{for(const key in keys)keys[key]=false;mouse.down=false;touchFire=false;touchBoost=false});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top});
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;mouse.down=true;canvas.setPointerCapture?.(e.pointerId)});
addEventListener('pointerup',()=>{mouse.down=false});
canvas.addEventListener('contextmenu',e=>e.preventDefault());

const joy=document.querySelector('#joy'),knob=document.querySelector('#joy-knob');let joyPointer=null;
function moveJoy(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=38,len=Math.hypot(dx,dy),scale=len>max?max/len:1;touchMove.x=dx*scale/max;touchMove.y=dy*scale/max;knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;touchMove.active=true}
joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);moveJoy(e)});
joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});
function releaseJoy(e){if(e.pointerId!==joyPointer)return;joyPointer=null;touchMove.active=false;touchMove.x=touchMove.y=0;knob.style.transform=''}
joy.addEventListener('pointerup',releaseJoy);joy.addEventListener('pointercancel',releaseJoy);
function bindHold(id,down,up){const el=document.querySelector(id);el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);down()});el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',up)}
bindHold('#touch-hit',()=>touchFire=true,()=>touchFire=false);
bindHold('#touch-boost',()=>{touchBoost=true;player.dash=.22},()=>touchBoost=false);
document.querySelector('#touch-interact').addEventListener('pointerdown',e=>{e.preventDefault();tryInteract()});
document.querySelector('#touch-melee').addEventListener('pointerdown',e=>{e.preventDefault();melee()});
</script></body></html>

