 .left-stack{position:absolute;left:22px;top:100px;width:255px;display:grid;gap:10px}.panel{background:var(--panel);border:1px solid #ffffff17;backdrop-filter:blur(10px);box-shadow:0 8px 30px #0003;padding:14px 15px}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:1.6px;color:var(--teal)}.mission-name{font:700 22px 'Barlow Condensed',sans-serif;letter-spacing:.8px;margin:4px 0}.mission-copy{font-size:11px;line-height:1.55;color:#aab8b4}.progress-row{display:flex;justify-content:space-between;align-items:center;margin-top:12px;font:10px 'DM Mono',monospace;color:#c5cfca}.progress-track{height:3px;background:#ffffff1a;margin-top:7px}.progress-fill{height:100%;width:0;background:var(--teal);transition:width .25s}.health-label{font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#98aaa5;display:flex;justify-content:space-between;margin-bottom:6px}.bars{height:7px;background:#ffffff17;margin-bottom:9px}.bar{height:100%;transition:width .2s}.health{background:linear-gradient(90deg,#ff765f,#ffb26d)}.xp{background:linear-gradient(90deg,#62e7bd,#9affdb)}.objective{font-size:11px;color:#e8ede8;margin-top:6px}.objective b{color:var(--teal)}.map-wrap{position:absolute;right:22px;top:100px;width:172px;height:172px;padding:5px;background:var(--panel);border:1px solid #ffffff22;box-shadow:0 8px 30px #0004}.map-title{position:absolute;right:0;top:-20px;font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#a5b5b0}.map-wrap canvas{width:100%;height:100%;display:block}.toast{position:absolute;top:26%;left:50%;transform:translate(-50%,-10px);padding:10px 18px;background:#111b1ad9;border:1px solid #ffffff25;font:11px 'DM Mono',monospace;letter-spacing:.8px;color:#f4f5ef;opacity:0;transition:.3s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom{position:absolute;left:22px;right:22px;bottom:18px;display:flex;align-items:flex-end;justify-content:space-between}.controls{display:flex;gap:7px;align-items:center}.key{display:inline-grid;place-items:center;